import test from 'node:test';import assert from 'node:assert/strict';import {createBoardFlow} from '../src/pixi/board-flow.js';import {productionBoardFlowOptions} from '../src/app/production-board-profile.js';import {installRightRoadResidualTrial,rightRoadTiltPositions} from '../src/pixi/right-road-residual-trial.js';import {RIGHT_ROAD_SOURCE,sourcePoint} from '../src/pixi/source-layout.js';
test('right trial anchors lowest pin and preserves all road pair distances, all other centres and all source guides',()=>{const p=createBoardFlow({lcd:true,...productionBoardFlowOptions()}).flow.physics,paths=structuredClone(p.sourceGuidePaths);for(let i=0;i<5;i++){const q=p.pins[96+i],[x,y]=sourcePoint(RIGHT_ROAD_SOURCE[i]);q.x=x;q.y=y;q.r=.2;delete q.shaftRadius;delete q.contactFriction;}const old=structuredClone(p.pins);installRightRoadResidualTrial(p);assert.deepEqual(p.sourceGuidePaths,paths);for(const pin of p.pins)if(pin.id<97||pin.id>101)assert.deepEqual(pin,old.find(q=>q.id===pin.id));const changed=p.pins.filter(p=>p.id>=97&&p.id<=101);assert.deepEqual([changed[0].x,changed[0].y],sourcePoint(RIGHT_ROAD_SOURCE[0]));for(let i=1;i<5;i++){assert.ok(Math.hypot(changed[i].x-old[96+i].x,changed[i].y-old[96+i].y)*2<4.7);assert.equal(changed[i].r,1.04);assert.equal(p.pinFrictionAt(changed[i]),.5);assert.equal(changed[i].restitution,old[96+i].restitution);}for(let i=0;i<5;i++)for(let j=i+1;j<5;j++)assert.ok(Math.abs(Math.hypot(changed[i].x-changed[j].x,changed[i].y-changed[j].y)-Math.hypot(old[96+i].x-old[96+j].x,old[96+i].y-old[96+j].y))<1e-10);assert.deepEqual(changed.map(({id,x,y})=>({id,x,y})),rightRoadTiltPositions());});


test('adopted production physics matches the reviewed in-memory overlay exactly',()=>{const actual=createBoardFlow({lcd:true,...productionBoardFlowOptions()}).flow.physics,reviewed=createBoardFlow({lcd:true,...productionBoardFlowOptions()}).flow.physics;for(let i=0;i<5;i++){const p=reviewed.pins[96+i],[x,y]=sourcePoint(RIGHT_ROAD_SOURCE[i]);p.x=x;p.y=y;p.r=.2;delete p.shaftRadius;delete p.contactFriction;}delete reviewed.rightRoadContactProfile;installRightRoadResidualTrial(reviewed);delete reviewed.rightRoadResidualTrial;assert.deepEqual(JSON.parse(JSON.stringify(actual)),JSON.parse(JSON.stringify(reviewed)));});
